import json

# Load all grids from the session
import os
import re

def load_grids():
    session = os.environ.get('RLM_SESSION_DIR')
    if not session:
        return {}

    fpath = os.path.join(session, '../../sessions/' + os.path.basename(session) + '.jsonl')
    fpath = os.path.normpath(fpath)

    try:
        with open(fpath, 'r') as f:
            content = f.read()
    except:
        return {}

    grids = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', content):
        k, ver_bw = m[1], m[3], m[4]
        h, w = int(ver_bw)

        rows = []
        remaining = content[m.end():].split('\n')
        for row in remaining:
            if row.strip():
                rows.append([int(x) for x in row.split()])
                if len(rows) >= h:
                    break

        grids[k] = rows  # store as list of row strings

    return grids

grids = load_grids()
print("Keys found:", sorted(grids.keys()))

# Parse the demo into actual integer grids
def parse_grid(grid_str):
    return [[int(x) for x in row.split()] for row in grid_str]

parsed_grids = {}
for k, v in grids.items():
    parsed_grids[k] = parse_grid(v)

print("\nTest input:")
print(parsed_grids.get('Test input (14x26)', 'Not found'))

print("\nDemo 1 input:")
d1_in = parsed_grids.get('Demo pair 1 input (30x22)', None)
if d1_in:
    for i, r in enumerate(d1_in):
        print(f"Row {i}: {r[:10]}..." if len(r) > 10 else f"Row {i}: {r}")

print("\nDemo 1 output:")
